using OcctSharp.Generator.Model;

namespace OcctSharp.Generator.Emission;

/// <summary>Emits compatibility adapters against the existing runtime registries and C ABI.</summary>
internal static class LegacyFoundationSupportEmitter
{
    private static readonly string[] Names = ["Collections", "Text", "Transient"];

    internal static IReadOnlyList<GeneratedFile> Emit() =>
        Names.Select(name => new GeneratedFile(
            "src/OcctSharp.Native/generated/Foundation/OcctSharp.Foundation.Legacy" + name + ".Generated.cpp",
            "// <auto-generated />\n// Compatibility template; no additional SDK declaration coverage is claimed.\n"
                + CopiedCollectionSupportEmitter.Template("legacy-foundation-" + name.ToLowerInvariant() + "-native.txt"),
            OcctProductModule.Foundation, GeneratedApiLayer.Runtime, "LegacyFoundation." + name)).ToArray();
}
